const source = $input.first().json;
const body = source.body && typeof source.body === 'object' ? source.body : source;
const text = (value) => typeof value === 'string' ? value.trim() : '';
const ticketId = text(body.ticket_id);
const subject = text(body.subject);
const message = text(body.message);
const email = text(body.customer_email).toLowerCase();
const tier = text(body.customer_tier).toLowerCase() || 'standard';
const channel = text(body.channel).toLowerCase() || 'webhook';
const affectedUsers = Number(body.affected_users ?? 0);
const errors = [];

if (ticketId.length < 1 || ticketId.length > 100) errors.push('ticket_id must be 1 to 100 characters');
if (subject.length < 3 || subject.length > 200) errors.push('subject must be 3 to 200 characters');
if (message.length < 10 || message.length > 5000) errors.push('message must be 10 to 5000 characters');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('customer_email must be valid');
if (!Number.isInteger(affectedUsers) || affectedUsers < 0 || affectedUsers > 1000000) {
  errors.push('affected_users must be an integer from 0 to 1000000');
}
if (!['standard', 'premium', 'enterprise'].includes(tier)) {
  errors.push('customer_tier must be standard, premium, or enterprise');
}

const occurredAt = text(body.occurred_at);
if (occurredAt && Number.isNaN(Date.parse(occurredAt))) errors.push('occurred_at must be an ISO-8601 date');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    received_at: new Date().toISOString(),
    ticket: {
      id: ticketId,
      subject,
      message,
      customer_email: email || null,
      customer_tier: tier,
      affected_users: Number.isFinite(affectedUsers) ? affectedUsers : 0,
      channel,
      occurred_at: occurredAt || null
    }
  }
}];

const input = $input.first().json;
const ticket = input.ticket;
const combined = `${ticket.subject} ${ticket.message}`.toLowerCase();
let score = 0;
const reasons = [];

const addOnce = (pattern, points, reason) => {
  if (pattern.test(combined)) {
    score += points;
    reasons.push(reason);
  }
};

addOnce(/\b(outage|down|unavailable|offline|production broken)\b/, 45, 'service outage');
addOnce(/\b(security|breach|hacked|compromised|ransomware|data leak)\b/, 50, 'security impact');
addOnce(/\b(payment|checkout|billing|charged|transaction)\b/, 25, 'payment impact');
addOnce(/\b(data loss|deleted|corrupt|missing data)\b/, 40, 'data integrity impact');
addOnce(/\b(urgent|immediately|critical|emergency)\b/, 15, 'urgent language');
addOnce(/\b(blocked|cannot work|can't work|stopped working)\b/, 15, 'customer blocked');

if (ticket.customer_tier === 'enterprise') {
  score += 20;
  reasons.push('enterprise customer');
} else if (ticket.customer_tier === 'premium') {
  score += 10;
  reasons.push('premium customer');
}

if (ticket.affected_users >= 100) {
  score += 25;
  reasons.push(`${ticket.affected_users} users affected`);
} else if (ticket.affected_users >= 10) {
  score += 15;
  reasons.push(`${ticket.affected_users} users affected`);
} else if (ticket.affected_users > 1) {
  score += 5;
  reasons.push(`${ticket.affected_users} users affected`);
}

score = Math.min(score, 100);
let severity = 'low';
let slaMinutes = 480;
let route = 'support_standard';
if (score >= 75) {
  severity = 'critical';
  slaMinutes = 15;
  route = 'on_call';
} else if (score >= 50) {
  severity = 'high';
  slaMinutes = 60;
  route = 'on_call';
} else if (score >= 25) {
  severity = 'medium';
  slaMinutes = 240;
  route = 'support_priority';
}

const redact = (value) => value
  .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[EMAIL_REDACTED]')
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[CARD_REDACTED]')
  .replace(/(?<!\w)(?:\+?\d[\d .()-]{7,}\d)(?!\w)/g, '[PHONE_REDACTED]');
const safePreview = redact(ticket.message).slice(0, 280);
const baseTime = ticket.occurred_at ? new Date(ticket.occurred_at) : new Date(input.received_at);
const acknowledgeBy = new Date(baseTime.getTime() + slaMinutes * 60_000).toISOString();

return [{
  json: {
    accepted: true,
    ticket_id: ticket.id,
    severity,
    score,
    route,
    is_urgent: severity === 'critical' || severity === 'high',
    sla_minutes: slaMinutes,
    acknowledge_by: acknowledgeBy,
    reasons: reasons.length ? reasons : ['no elevated risk signals'],
    safe_preview: safePreview,
    received_at: input.received_at
  }
}];

const input = $input.first().json;
return [{
  json: {
    accepted: false,
    error: 'invalid_ticket',
    details: input.errors,
    received_at: input.received_at
  }
}];
